    private void btnIngresarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnIngresarActionPerformed
    String usuario = txtUsuario.getText().trim();
    String pass = new String(txtContraseña.getPassword()).trim();

    if (usuario.isEmpty() || pass.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Por favor llena todos los campos.", "Aviso", javax.swing.JOptionPane.WARNING_MESSAGE);
        return;
    }

    // Consulta a la base de datos usando la clase Conexion
    String sql = "SELECT rol FROM empleados WHERE usuario = ? AND contrasena = ?";
    try (java.sql.Connection con = Conexion.getConexion();
         java.sql.PreparedStatement ps = con.prepareStatement(sql)) {

        ps.setString(1, usuario);
        ps.setString(2, pass);
        java.sql.ResultSet rs = ps.executeQuery();

        if (rs.next()) {
            String rol = rs.getString("rol").toLowerCase();
            javax.swing.JOptionPane.showMessageDialog(this, "Bienvenido " + usuario + " [" + rol.toUpperCase() + "]");

            // Redirección según el rol
            switch (rol) {
                case "administrador":
                case "admin":
                    Alimentos ventanaAlimentos = new Alimentos();
                    ventanaAlimentos.setVisible(true); // Abre la interfaz de Alimentos
                    this.dispose(); // Cierra la ventana de Login
                    break;
                case "mesero":
                    Mesa ventanaMesa = new Mesa();
                    ventanaMesa.setVisible(true);
                    this.dispose();
                    break;
                case "cocinero":
                    Orden ventanaOrden = new Orden();
                    ventanaOrden.setVisible(true);
                    this.dispose();
                    break;
                case "cajero":
                    Clientes ventanaClientes = new Clientes();
                    ventanaClientes.setVisible(true);
                    this.dispose();
                    break;
                default:
                    javax.swing.JOptionPane.showMessageDialog(this, "Rol no reconocido.", "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
            }
        } else {
            javax.swing.JOptionPane.showMessageDialog(this, "Usuario o contraseña incorrectos", "Error de Acceso", javax.swing.JOptionPane.ERROR_MESSAGE);
        }
    } catch (Exception ex) {
        javax.swing.JOptionPane.showMessageDialog(this, "Error de conexión a la BD: " + ex.getMessage(), "Error BD", javax.swing.JOptionPane.ERROR_MESSAGE);
    }
    }//GEN-LAST:event_btnIngresarActionPerformed

